 useEffect(()=>{if(!jobId)return;let active=true;setLoading(true);const ids=jobId==='*'?jobs.map(job=>job.id):[jobId];void Promise.all([backend.requests.list(),...ids.map(id=>backend.matching.list(id))]).then(([rows,...lists])=>{if(!active)return;setRequests(rows as AccessRequest[]);setPeople(withRequestStatus((lists as Candidate[][]).flat(),rows as AccessRequest[]))}).catch(()=>{if(active){setRequests([]);setPeople([]);setNotice('We couldn’t load pipeline data. Check your connection and try again.')}}).finally(()=>{if(active)setLoading(false)});let unsubscribe:()=>void=()=>{};void backend.notifications.subscribe(loadRequests).then(stop=>{unsubscribe=stop});const timer=window.setInterval(loadRequests,30000);return()=>{active=false;unsubscribe();window.clearInterval(timer)}},[jobId,jobs]);
